"""Analyze existing JPEG frames generated by `sample`, without re-reading the video.

This is a visual/calibration smoke test. The actual deployment pipeline should
calibrate against frame timestamps measured from the MP4, not inferred filenames.
"""
from __future__ import annotations

import re
from pathlib import Path
from typing import Any

import cv2
import numpy as np

from .clock import ROI, read_clock, read_clock_crop, clock_text
from .media import save_jpg
from .sync import build_segments, observations_from_scans, pick_second_mode

FRAME_NAME = re.compile(r"frame_(\d+)_(\d+)s\.jpg$")


def parse_sample_files(folder: Path, *, duration: float) -> list[tuple[Path, float]]:
    matches: list[tuple[int, int, Path]] = []
    for path in folder.glob("frame_*.jpg"):
        m = FRAME_NAME.fullmatch(path.name)
        if m:
            matches.append((int(m.group(1)), int(m.group(2)), path))
    matches.sort()
    n = len(matches)
    if n < 2:
        raise ValueError(f"No hay suficientes fotogramas frame_NN_SSSSSSs.jpg en {folder}")
    if [i for i, _, _ in matches] != list(range(1, n + 1)):
        raise ValueError("Faltan muestras o hay índices duplicados. Repite `sample` en otra carpeta vacía.")
    result = []
    for i, nominal_sec, path in matches:
        # V1 and V2 `sample` use the exact fractional instant duration*i/(n+1).
        t = duration * i / (n + 1)
        if abs(int(t) - nominal_sec) > 0:
            raise ValueError(f"{path.name}: el tiempo no coincide con el vídeo. No se atribuirá un reloj al instante equivocado.")
        result.append((path, t))
    return result


def analyze_samples(files: list[tuple[Path, float]], roi: ROI,
                    first_window: tuple[float, float],
                    second_window: tuple[float, float],
                    second_mode: str = "auto", min_votes: int = 2,
                    tolerance: float = 4.0, max_gap: float = 2400.0,
                    debug_dir: Path | None = None,
                    clock_detection: dict | None = None,
                    require_marker_evidence: bool = True) -> dict[str, Any]:
    if first_window[1] >= second_window[0]:
        raise ValueError("Las ventanas de las partes se solapan; revisa los tiempos de vídeo.")
    if min_votes not in (1, 2, 3):
        raise ValueError("--min-votes debe estar entre 1 y 3.")
    scans = []
    crop_audits = []
    for path, video_second in files:
        period = ("first" if first_window[0] <= video_second <= first_window[1]
                  else "second" if second_window[0] <= video_second <= second_window[1]
                  else "outside")
        frame = cv2.imread(str(path))
        if frame is None:
            raise ValueError(f"No se pudo abrir: {path}")
        if require_marker_evidence:
            reading = read_clock(frame, roi, min_votes=min_votes)
        else:
            reading = read_clock_crop(roi.crop(frame), min_votes=min_votes,
                                      require_marker_evidence=False)
        item = {"source": path.name, "video_second": round(video_second, 3),
                "period": period, **reading}
        scans.append(item)
        crop = roi.crop(frame)
        big = cv2.resize(crop, (436, 156), interpolation=cv2.INTER_CUBIC)
        crop_audits.append((big, item))

    if clock_detection:
        for scan, evidence in zip(scans, clock_detection.get("sample_evidence", [])):
            if (evidence.get("status") == "marker_not_visible" and
                    scan["status"] != "valid_reading"):
                scan["status"] = "marker_not_visible"
                scan["status_reason"] = evidence.get("reason")

    valid_first = [s for s in scans if s["period"] == "first" and
                   s["status"] == "valid_reading" and
                   s["clock_seconds"] < 60*60]
    valid_second = [s for s in scans if s["period"] == "second" and
                    s["status"] == "valid_reading"]
    mode = second_mode
    if mode == "auto" and valid_second:
        mode = pick_second_mode([s["clock_seconds"] for s in valid_second])
    observations = observations_from_scans(
        scans, second_mode=mode, tolerance_seconds=tolerance,
        max_gap_seconds=max_gap,
    )
    segments = build_segments(observations, tolerance_seconds=tolerance,
                              max_gap_seconds=max_gap)
    if debug_dir:
        debug_dir.mkdir(parents=True, exist_ok=True)
        crops = []
        for big, scan in crop_audits:
            # Diagnostic labels are outside the TV pixels and preserve each
            # distinction made by the OCR and temporal validation stages.
            status_labels = {
                "valid_reading": "LECTURA VALIDA",
                "marker_not_visible": "MARCADOR NO VISIBLE",
                "ambiguous_invalid": "OCR AMBIGUO / INVALIDO",
                "suspicious_discontinuity": "DISCONTINUIDAD SOSPECHOSA",
            }
            shown_clock = scan.get("clock")
            if shown_clock is None and scan.get("candidate_clock_seconds") is not None:
                shown_clock = f"candidato {clock_text(scan['candidate_clock_seconds'])}"
            label = (f"{clock_text(scan['video_second'])}  OCR: {shown_clock or '---'}"
                     f" ({scan['votes']}/3) [{scan['period']}] "
                     f"{status_labels.get(scan['status'], scan['status'])}")
            canvas = cv2.copyMakeBorder(big, 0, 46, 0, 0, cv2.BORDER_CONSTANT,
                                        value=(35,35,35))
            cv2.putText(canvas, label, (7, 184), cv2.FONT_HERSHEY_SIMPLEX,
                        0.43, (255,255,255), 1, cv2.LINE_AA)
            crops.append(canvas)
        # Contact sheet of the ACTUAL clocks; fixed consistent canvas sizes.
        for j in range(0, len(crops), 4):
            save_jpg(debug_dir / f"clocks_{j//4 + 1:02d}.jpg", cv2.vconcat(crops[j:j+4]))
    status_counts: dict[str, int] = {}
    for scan in scans:
        status_counts[scan["status"]] = status_counts.get(scan["status"], 0) + 1
    return {
        "version": 3,
        "source": "Existing JPEG samples, timestamps reconstructed from sample indices and video duration",
        "roi": roi.as_dict(), "clock_detection": clock_detection,
        "parameters": {"first_window": first_window, "second_window": second_window,
                       "second_clock_mode": mode, "min_votes": min_votes,
                       "offset_tolerance_seconds": tolerance, "max_gap_seconds": max_gap,
                       "temporal_check_max_gap_seconds": max_gap},
        "segments": segments, "scans": scans, "status_counts": status_counts,
        "warnings": [
            "Muestras JPEG dispersas: no detectan cortes o congelaciones entre capturas.",
            "Las referencias temporales de sample corresponden al tiempo FFmpeg solicitado; valídalas contra el archivo.",
            "La ausencia del marcador no crea por sí sola una discontinuidad; las lecturas posteriores se comparan con la última lectura válida.",
            "Una discontinuidad temporal sospechosa exige referencias compatibles propias antes de formar otro segmento.",
            "La coincidencia temporal no identifica el segundo exacto de la acción de SofaScore.",
        ],
    }
